def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    change_ratio = (change / v1) * 100

    return {
        "value": change_ratio,
        "trace": {
            "initial_balance_2006": v1,
            "final_balance_2007": v2,
            "absolute_change": change,
            "change_ratio_percent": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "percentage"
            }
        }
    }
